//! 🧪️ Actual typed Window registration keeps private rows invisible and cancels every original admission prefix.
use semio_framework_plugin_window_config::{WindowConfigOwnerRegistry,OriginalWindowOwnerRegistration};
use semio_framework_job::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
const TURN:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:4096};
fn observed_with<T>(grant:RetainedCloneGrant,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,f:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant,decoder,f));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"Window registration receipt={p:?}, failure={:?}",result.as_ref().err());result.unwrap()}
fn observed<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,f:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{observed_with(TURN,caller,decoder,f)}
#[test]
fn original_window_owner_registration_publishes_or_cancels_each_private_prefix(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for cutoff in std::iter::once(usize::MAX).chain(law["cancelAfter"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as usize)){let mut registry=WindowConfigOwnerRegistry::new(semio_framework_os_kernel::ActorId("original-window-registry".into()));let mut caller=OriginalJobFixtureCaller::admit(OperationId(87621),Generation(11),RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<26,maximum_release_bytes:1<<27,maximum_depth:4096},default_now_us,u64::MAX,1<<24);let mut decoder=OriginalJobDecodeOwner::empty();let mut owner=None;observed(&mut caller,&mut decoder,|cx|registry.admit_original_owner::<crate::fixture::Owner>(cx,&mut owner));assert!(OriginalWindowOwnerRegistration::<crate::fixture::Owner>::owner_birth_demands().copy_bytes>TURN.maximum_copy_bytes);assert!(!observed(&mut caller,&mut decoder,|cx|owner.as_mut().unwrap().step(&mut registry,cx)));assert_eq!(caller.receipt(),RetainedCloneProgress::default());for axis in 0..4{let mut denied=semio_framework_plugin_mounted_owner::MountedOwnerPolicyV1::INTERACTIVE_COMPONENT.preparation;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=0,2=>denied.maximum_capacity_bytes=0,_=>denied.maximum_depth=0}assert!(!observed_with(denied,&mut caller,&mut decoder,|cx|owner.as_mut().unwrap().step(&mut registry,cx)));assert_eq!(caller.receipt(),RetainedCloneProgress::default());assert!(registry.is_empty());}let mut foreign=OriginalJobFixtureCaller::admit(OperationId(87622),Generation(11),RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<26,maximum_release_bytes:1<<27,maximum_depth:4096},default_now_us,u64::MAX,1<<24);let mut foreign_decoder=OriginalJobDecodeOwner::empty();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn_with_decoder(TURN,&mut foreign_decoder,|cx|owner.as_mut().unwrap().step(&mut registry,cx)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(foreign.receipt(),RetainedCloneProgress::default());assert!(foreign_decoder.terminal_is_empty());foreign.retire(TURN);let mut ready=false;for step in 0..cutoff.min(256){ready=observed_with(if step==0{semio_framework_plugin_mounted_owner::MountedOwnerPolicyV1::INTERACTIVE_COMPONENT.preparation}else{TURN},&mut caller,&mut decoder,|cx|owner.as_mut().unwrap().step(&mut registry,cx));if ready{break}assert!(registry.is_empty(),"a private registration row became visible before publication");assert!(step<255,"registration birth {:?}, source receipt {:?}",OriginalWindowOwnerRegistration::<crate::fixture::Owner>::owner_birth_demands(),caller.receipt())}if cutoff==usize::MAX{assert!(ready);assert!(!registry.is_empty())}caller.cancel().cancel_now();for turn in 0..65536{if owner.as_ref().unwrap().terminal_is_empty(){break}observed_with(semio_framework_plugin_mounted_owner::MountedOwnerPolicyV1::INTERACTIVE_COMPONENT.close,&mut caller,&mut decoder,|cx|owner.as_mut().unwrap().close_step(&mut registry,cx));assert!(turn<65535)}let d=OriginalWindowOwnerRegistration::<crate::fixture::Owner>::boxed_release_demands();observed(&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));for turn in 0..65536{if registry.terminal_is_empty(){break}observed_with(semio_framework_plugin_mounted_owner::MountedOwnerPolicyV1::INTERACTIVE_COMPONENT.close,&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|{let before=cx.retained_progress();let grant=cx.retained_grant();let step=registry.close_step_context(grant,cx).map_err(OriginalTurnFailure::from)?;let unposted=semio_framework_plugin_ownership::bounded_ownership::original_lifecycle_unposted(step.progress().unwrap_or_default(),before,cx.retained_progress())?;cx.consume_retained(unposted)?;cx.consume_fuel(unposted.copied_items as u64);Ok(())}));assert!(turn<65535)}assert!(registry.terminal_is_empty());while !decoder.terminal_is_empty(){caller.turn(TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(TURN);}}
